generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
       (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
       (SUM(xsd:decimal(?raAmount)) AS ?totalRebalancingAmount)
       (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange)
       ?riskScore
       ?goalMatchPct
WHERE {
  # Cash Flow per investor
  {
    SELECT ?investorId ?cfAmount
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    }
  }
  # Rebalancing Action per investor
  {
    SELECT ?investorId ?raAmount
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmount .
    }
  }
  # Scenario Rebalancing change per investor
  {
    SELECT ?investorId ( (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioChange )
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:currentAllocationPct ?currAlloc ;
          wm:newAllocationPct ?newAlloc .
    }
  }
  # Portfolio Health metrics (unique per investor)
  {
    SELECT ?investorId ?riskScore ?goalMatchPct
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:goalMatchPct ?goalMatchPct .
    }
  }
}
GROUP BY ?investorId ?riskScore ?goalMatchPct
ORDER BY ?investorId

